package cz.recaption.core

/**
 * Nápověda jako postup od začátku (od 0.97, `help()` v MainActivity): kapitoly `hc<číslo>_…` podle
 * zvolené televize a konzole, výběr „Nápověda pro“ (`help_for`), a drobné texty z téže verze
 * (náhled `pv_stale`, převzetí Remote Play `ls_other_device`, aktuální aplikace v televizi)
 * a videonávody (`vg_…`, od 0.97.71: dřív i názvy celých videí, od 1.00-rc14 zrušené; na stránce Videonávody, `core/VideoGuide`, a chyba
 * přehrávače `VideoGuideActivity`).
 * HELP_S = čeština a slovenština, HELP_X = ostatní jazyky.
 */
internal val HELP_S: Map<String, Pair<String, String>> = mapOf(
    "help_for" to ("Instalace pro" to "Inštalácia pre"),
    "hc1" to ("1. Instalace ReCaptionu" to "1. Inštalácia ReCaptionu"),
    "hc1_android" to ("ReCaption patří do Android TV nebo boxu s Androidem, který je zapojený v televizi. Soubor ReCaption.apk se nahraje aplikací Downloader – v ní stačí zadat kód 8438934 (záložně adresa ze stránky s návodem), nebo z flash disku správcem souborů. Další verze už se nabídnou samy na Domů." to "ReCaption patrí do Android TV alebo boxu s Androidom, ktorý je zapojený v televízore. Súbor ReCaption.apk sa nahrá aplikáciou Downloader – v nej stačí zadať kód 8438934 (záložne adresa zo stránky s návodom), alebo z flash disku správcom súborov. Ďalšie verzie sa už ponúknu samy na Domov."),
    "hc1_reader" to ("Televize LG a Samsung si obraz hry samy nepřečtou. ReCaption proto běží v telefonu s Androidem (nebo v boxu): čte obraz z konzole, překládá a hotové titulky posílá do aplikace ReCaption v televizi. Do telefonu se stáhne a nainstaluje ReCaption.apk (odkaz je na stránce s návodem)." to "Televízory LG a Samsung si obraz hry samy neprečítajú. ReCaption preto beží v telefóne s Androidom (alebo v boxe): číta obraz z konzoly, prekladá a hotové titulky posiela do aplikácie ReCaption v televízore. Do telefónu sa stiahne a nainštaluje ReCaption.apk (odkaz je na stránke s návodom)."),
    "hc2" to ("2. Příprava konzole" to "2. Príprava konzoly"),
    "hc2_ps" to ("Na PS5 je potřeba založit druhého uživatele s jiným účtem PlayStation (zdarma) – 🔵 účet pro ReCaption. Aplikace se připojuje jím – kdyby se připojila 🟢 herním účtem, konzole by při hraní vypínala ovladač. Účet založený na webu je potřeba na PS5 ještě přidat: ikona profilu → Přepnout uživatele → Přidat uživatele a přihlásit se 🔵 účtem (ne jako host). Pod 🔵 druhým uživatelem zapnout Nastavení → Systém → Aplikace Remote Play → Povolit aplikaci Remote Play. Hraje se pak normálně pod 🟢 herním účtem." to "Na PS5 treba založiť druhého používateľa s iným účtom PlayStation (zadarmo) – 🔵 účet pre ReCaption. Aplikácia sa pripája ním – keby sa pripojila 🟢 herným účtom, konzola by pri hraní vypínala ovládač. Účet založený na webe treba na PS5 ešte pridať: ikona profilu → Prepnúť používateľa → Pridať používateľa a prihlásiť sa 🔵 účtom (nie ako hosť). Pod 🔵 druhým používateľom zapnúť Nastavenia → Systém → Remote Play → Povoliť Remote Play. Hrá sa potom normálne pod 🟢 herným účtom."),
    "hc2_xbox" to ("Na Xboxu zapnout Nastavení → Zařízení a připojení → Vzdálené funkce a režim napájení nechat „Spánek“ (ne úsporný). V ReCaptionu pak na stránce Xbox přihlásit účet Microsoft kódem na microsoft.com/link a vybrat Xbox." to "Na Xboxe zapnúť Nastavenia → Zariadenia a pripojenia → Vzdialené funkcie a režim napájania nechať „Spánok“ (nie úsporný). V ReCaptione potom na stránke Xbox prihlásiť účet Microsoft kódom na microsoft.com/link a vybrať Xbox."),
    "hc3" to ("3. Televize" to "3. Televízor"),
    "hc3_android" to ("Pruh s překladem kreslí ReCaption přes obraz hry. Povoluje se v nastavení televize: Usnadnění → ReCaption → Zapnout (případně „Zobrazení přes jiné aplikace“). Když televize tu obrazovku nemá, jde to povolit z počítače:" to "Pruh s prekladom kreslí ReCaption cez obraz hry. Povoľuje sa v nastaveniach televízora: Zjednodušenie ovládania → ReCaption → Zapnúť (prípadne „Zobrazenie cez iné aplikácie“). Keď televízor tú obrazovku nemá, dá sa to povoliť z počítača:"),
    "hc3_lg" to ("Do televize LG patří aplikace ReCaption (obrazovka s hrou a pruhem). Nahraje se z tohoto zařízení přes vývojářský režim LG – pomocník provede krok za krokem a hotové kroky odškrtá sám. Vývojářský režim po čase vyprší, Domů včas upozorní. Tohle zařízení musí být ve stejné domácí síti jako televize. Prodloužit vývojářský režim jde v televizi v aplikaci Developer Mode (Extend), nebo ho ReCaption prodlouží sám jednou denně s volbou ⚙ → Obecné → Prodlužovat vývojářský režim. Když vyprší, ReCaption z televize zmizí a nahraje se znovu. Jde to i z počítače nástrojem LG ares (postup na recaption.pages.dev/lg.html#pocitac složka webos)." to "Do televízora LG patrí aplikácia ReCaption (obrazovka s hrou a pruhom). Nahrá sa z tohto zariadenia cez vývojársky režim LG – pomocník prevedie krok za krokom a hotové kroky odškrtne sám. Vývojársky režim po čase vyprší, Domov včas upozorní. Toto zariadenie musí byť v rovnakej domácej sieti ako televízor. Predĺžiť vývojársky režim ide v televízore v aplikácii Developer Mode (Extend), alebo ho ReCaption predĺži sám raz denne s voľbou ⚙ → Všeobecné → Predlžovať vývojársky režim. Keď vyprší, ReCaption z televízora zmizne a nahrá sa znova. Dá sa to aj z počítača nástrojom LG ares (postup na recaption.pages.dev/lg.html#pocitac priečinok webos)."),
    "hc4" to ("4. Jazyk a kvalita překladu" to "4. Jazyk a kvalita prekladu"),
    "hc4_text" to ("Jazyk překladu se vybírá v Titulkách. Pod ním je „Překládat z“ – jazyk titulků ve hře (výchozí angličtina). Jazykový balíček se stáhne jednou (asi 30 MB) a pak se překládá offline a zdarma. Lepší překlad přes DeepL (vlastní klíč zdarma) se nastaví v Titulkách → Kvalita překladu: na televizi stačí naskenovat jeden čtvereček – stránka v telefonu provede registrací na DeepL, zkopírováním i vložením klíče." to "Jazyk prekladu sa vyberá v Titulkoch. Pod ním je „Prekladať z“ – jazyk titulkov v hre (predvolene angličtina). Jazykový balík sa stiahne raz (asi 30 MB) a potom sa prekladá offline a zadarmo. Lepší preklad cez DeepL (vlastný kľúč zadarmo) sa nastaví v Titulkoch → Kvalita prekladu: na televízore stačí naskenovať jeden štvorček – stránka v telefóne prevedie registráciou na DeepL, skopírovaním aj vložením kľúča."),
    "hc5" to ("5. Spárování konzole" to "5. Spárovanie konzoly"),
    "hc5_text" to ("Jednou a podle průvodce na stránce Konzole: zvolit 🔵 druhý účet (pro ReCaption), přihlásit ho telefonem (čtvereček) a na PS5 pod stejným uživatelem zapnout Remote Play a vyvolat osmimístné číslo. Když ho vyvolá jiný uživatel, PS5 hlásí CE‑110032‑7. Pak se na PS5 přepnout zpět na 🟢 herní účet." to "Raz a podľa sprievodcu na stránke Konzola: zvoliť 🔵 druhý účet (pre ReCaption), prihlásiť ho telefónom (štvorček) a na PS5 pod rovnakým používateľom zapnúť Remote Play a vyvolať osemmiestne číslo. Keď ho vyvolá iný používateľ, PS5 hlási CE‑110032‑7. Potom sa na PS5 prepnúť späť na 🟢 herný účet."),
    "hc5_xbox" to ("Jednou na stránce Xbox (menu Konzole): Přihlásit účet Microsoft → v telefonu nebo počítači otevřít microsoft.com/link (nebo naskenovat čtvereček), zadat kód z obrazovky a přihlásit se účtem Microsoft, kterým se na Xboxu hraje – druhý účet tu není potřeba. E-mail a heslo se píšou jen na stránce Microsoftu, ne do ReCaptionu. Pak vybrat Xbox, na kterém se hraje." to "Raz na stránke Xbox (menu Konzola): Prihlásiť účet Microsoft → v telefóne alebo počítači otvoriť microsoft.com/link (alebo naskenovať štvorček), zadať kód z obrazovky a prihlásiť sa účtom Microsoft, ktorým sa na Xboxe hrá – druhý účet tu netreba. E-mail a heslo sa píšu len na stránke Microsoftu, nie do ReCaptionu. Potom vybrať Xbox, na ktorom sa hrá."),
    "hc6" to ("6. Hraní" to "6. Hranie"),
    "hc6_android" to ("Na Domů spustit překlad, počkat na „obraz přichází“ a přepnout televizi na HDMI s konzolí. Ve hře musí být zapnuté anglické titulky. Vzhled a poloha pruhu se mění v Titulkách." to "Na Domov spustiť preklad, počkať na „obraz prichádza“ a prepnúť televízor na HDMI s konzolou. V hre musia byť zapnuté anglické titulky. Vzhľad a poloha pruhu sa mení v Titulkoch."),
    "hc6_tv" to ("V ReCaptionu (telefon) spustit překlad. V televizi otevřít aplikaci ReCaption a vybrat HDMI s konzolí – telefon najde sama. Ve hře musí být zapnuté anglické titulky. Vzhled pruhu se mění v Titulkách v telefonu, nebo při hře tlačítkem OK na ovladači televize. Telefon může ležet, ideálně na nabíječce; displej nemá zhasnout – ⚙ Nastavení → Obecné → „Nezhasínat displej telefonu“." to "V ReCaptione (telefón) spustiť preklad. V televízore otvoriť aplikáciu ReCaption a vybrať HDMI s konzolou – telefón nájde sama. V hre musia byť zapnuté anglické titulky. Vzhľad pruhu sa mení v Titulkoch v telefóne, alebo pri hre tlačidlom OK na ovládači televízora. Telefón môže ležať, ideálne na nabíjačke; displej nemá zhasnúť – ⚙ Nastavenia → Všeobecné → „Nezhasínať displej telefónu“."),
    "hc7" to ("7. Když něco nejde" to "7. Keď niečo nejde"),
    "hc7_qr" to ("Stránka ze čtverečku se v telefonu neotevře: telefon musí být na stejné Wi-Fi (ne na mobilních datech)." to "Stránka zo štvorčeka sa v telefóne neotvorí: telefón musí byť na rovnakej Wi-Fi (nie na mobilných dátach)."),
    "hc7_ps5" to ("Konzole se nepřipojí: zkontrolovat Remote Play pod druhým uživatelem a že konzole i toto zařízení jsou ve stejné síti." to "Konzola sa nepripojí: skontrolovať Remote Play pod druhým používateľom a že konzola aj toto zariadenie sú v rovnakej sieti."),
    "hc7_net" to ("Spojení vypadává: na Wi-Fi 2,4 GHz vysílají ve stejném pásmu i ovladače konzole. Pomůže připojit konzoli k routeru kabelem, nebo přepnout toto zařízení na Wi-Fi 5 GHz." to "Spojenie vypadáva: na Wi-Fi 2,4 GHz vysielajú v rovnakom pásme aj ovládače konzoly. Pomôže pripojiť konzolu k routeru káblom, alebo prepnúť toto zariadenie na Wi-Fi 5 GHz."),
    "hc7_battery" to ("Telefon: spojení vypadává se zhasnutým displejem – v ⚙ Nastavení → Obecné zapnout „Povolit běh na pozadí“ (šetření baterie ReCaption uspává)." to "Telefón: spojenie vypadáva so zhasnutým displejom – v ⚙ Nastaveniach → Všeobecné zapnúť „Povoliť beh na pozadí“ (šetrenie batérie ReCaption uspáva)."),
    "hc7_screen" to ("Telefon: se zhasnutým displejem se překlad zpomalí nebo skoro zastaví (Samsung čte titulky až 10× pomaleji) – v ⚙ Nastavení → Obecné zapnout „Nezhasínat displej telefonu“ (displej zůstane ztlumený), telefon ideálně na nabíječce." to "Telefón: so zhasnutým displejom sa preklad spomalí alebo skoro zastaví (Samsung číta titulky až 10× pomalšie) – v ⚙ Nastaveniach → Všeobecné zapnúť „Nezhasínať displej telefónu“ (displej zostane stlmený), telefón ideálne na nabíjačke."),
    "hc7_other" to ("Na PS5 naskakuje „ovladač odpojen / účet připojen“: se stejným druhým účtem se připojuje jiné zařízení (třeba aplikace PS Remote Play). Druhý účet má sloužit jen ReCaptionu." to "Na PS5 naskakuje „ovládač odpojený / účet pripojený“: s rovnakým druhým účtom sa pripája iné zariadenie (napríklad aplikácia PS Remote Play). Druhý účet má slúžiť len ReCaptionu."),
    "hc7_read" to ("Titulky nenaskakují: zapnout ⚙ Nastavení → Experimentální → Diagnostický režim – ukáže, co aplikace čte. Pomůže i hlášení chyby poslané do telefonu." to "Titulky nenaskakujú: zapnúť ⚙ Nastavenia → Experimentálne → Diagnostický režim – ukáže, čo aplikácia číta. Pomôže aj hlásenie chyby poslané do telefónu."),
    "hc8" to ("8. Volby v Nastavení" to "8. Voľby v Nastaveniach"),
    "hc9" to ("9. Víc TV nebo konzolí" to "9. Viac TV alebo konzol"),
    "hc9_text" to ("•  Další PS5: stránka Konzole → „Spárovat další PS5“; mezi spárovanými se přepíná řádkem „Aktivní PS5“.\n•  PS5 i Xbox: ⚙ Nastavení → Obecné → Konzole; spárování i přihlášení zůstanou uložené.\n•  Dvě TV LG / Samsung, jeden telefon: vzhled titulků a oblasti si telefon pamatuje pro každou TV zvlášť.\n•  Dvě Android TV: ReCaption do každé zvlášť, každá má vlastní nastavení." to "•  Ďalšia PS5: stránka Konzola → „Spárovať ďalšiu PS5“; medzi spárovanými sa prepína riadkom „Aktívna PS5“.\n•  PS5 aj Xbox: ⚙ Nastavenia → Všeobecné → Konzola; spárovanie aj prihlásenie zostanú uložené.\n•  Dva TV LG / Samsung, jeden telefón: vzhľad titulkov a oblasti si telefón pamätá pre každý TV zvlášť.\n•  Dva Android TV: ReCaption do každého zvlášť, každý má vlastné nastavenia."),
    "hm_row" to ("Víc TV nebo konzolí" to "Viac TV alebo konzol"),
    "help_page" to ("Stránka s návodem" to "Stránka s návodom"),
    "ls_other_device" to ("Remote Play na PS5 teď používá jiné zařízení se stejným účtem (třeba aplikace PS Remote Play). ReCaption se připojí, až ho uvolní." to "Remote Play na PS5 teraz používa iné zariadenie s rovnakým účtom (napríklad aplikácia PS Remote Play). ReCaption sa pripojí, keď ho uvoľní."),
    "pv_stale" to ("Náhled je poslední přijatý snímek – teď obraz nepřichází:" to "Náhľad je posledná prijatá snímka – teraz obraz neprichádza:"),
    "lg_launch" to ("Spustit ReCaption v TV" to "Spustiť ReCaption v TV"),
    "tv_current" to ("ReCaption v TV · verze %s" to "ReCaption v TV · verzia %s"),
    "lg_pass_other" to ("Zadat Passphrase znovu" to "Zadať Passphrase znova"),
    "vg_error" to ("Video se nepodařilo načíst. Zkontrolovat připojení k internetu, nebo otevřít adresu v prohlížeči:" to "Video sa nepodarilo načítať. Skontrolovať pripojenie k internetu, alebo otvoriť adresu v prehliadači:"),
)

internal val HELP_X: Map<Lang, Map<String, String>> = mapOf(
    Lang.EN to mapOf(
        "help_for" to "Setup for",
        "hc1" to "1. Installing ReCaption",
        "hc1_android" to "ReCaption goes on the Android TV or Android box connected to the TV. Install ReCaption.apk with the Downloader app – just enter the code 8438934 there (fallback: the address on the guide page) or from a USB stick with a file manager. Later versions are offered automatically on Home.",
        "hc1_reader" to "LG and Samsung TVs can’t read the game picture themselves. So ReCaption runs on an Android phone (or a box): it reads the picture from the console, translates and sends the finished subtitles to the ReCaption app on the TV. Download ReCaption.apk to the phone and install it (the link is on the guide page).",
        "hc2" to "2. Preparing the console",
        "hc2_ps" to "On the PS5 add a second user with another PlayStation account (free) – the 🔵 account for ReCaption. The app connects with it – if it used your 🟢 gaming account, the console would turn off your controller while you play. An account created on the web must still be added on the PS5: profile icon → Switch User → Add User, then sign in with the 🔵 account (not as a guest). Under the 🔵 second user turn on Settings → System → Remote Play → Enable Remote Play. You then play as usual under your own 🟢 gaming account.",
        "hc2_xbox" to "On the Xbox turn on Settings → Devices & connections → Remote features and keep the power mode at “Sleep” (not energy saving). Then on the Xbox page in ReCaption sign in with a Microsoft account using the code at microsoft.com/link and choose your Xbox.",
        "hc3" to "3. TV",
        "hc3_android" to "ReCaption draws the translation bar over the game picture. Allow it in the TV settings: Accessibility → ReCaption → On (or “Display over other apps”). If the TV doesn’t have that screen, it can be allowed from a computer:",
        "hc3_lg" to "The ReCaption app goes on the LG TV (a screen with the game and the bar). It is installed from this device via LG Developer Mode – the helper guides you step by step and ticks off finished steps by itself. Developer Mode expires after a while; Home warns you in time. This device must be in the same home network as the TV. Developer Mode can be extended on the TV in the Developer Mode app (Extend), or ReCaption extends it once a day with the option ⚙ → General → Extend Developer Mode. When it expires, ReCaption disappears from the TV and is installed again. It can also be installed from a computer with the LG tool ares (see recaption.pages.dev/lg.html#pocitac folder webos).",
        "hc4" to "4. Language and translation quality",
        "hc4_text" to "Choose the translation language in Subtitles. Below it, “Translate from” is the language of the game’s subtitles (English by default). The language pack downloads once (about 30 MB), then translation is offline and free. Better translation with DeepL (your own free key) is set up in Subtitles → Translation quality: on the TV just scan one QR code – the page on your phone walks you through DeepL sign-up, copying and pasting the key.",
        "hc5" to "5. Pairing the console",
        "hc5_text" to "Once, following the guide on the Console page: choose the 🔵 second account (for ReCaption), sign it in with your phone (QR code), then on the PS5, as the same user, turn on Remote Play and get the eight-digit number. If another user gets the number, the PS5 shows CE‑110032‑7. Then switch the PS5 back to your 🟢 gaming account.",
        "hc5_xbox" to "Once, on the Xbox page (Console menu): Sign in with a Microsoft account → on a phone or computer open microsoft.com/link (or scan the square), enter the code shown and sign in with the Microsoft account you play with on the Xbox – no second account is needed here. E-mail and password are typed only on Microsoft’s page, not into ReCaption. Then choose the Xbox you play on.",
        "hc6" to "6. Playing",
        "hc6_android" to "Start the translation on Home, wait for “the picture is arriving” and switch the TV to the console’s HDMI. Keep English subtitles on in the game. Change the bar’s look and position in Subtitles.",
        "hc6_tv" to "Start the translation in ReCaption (phone). On the TV open the ReCaption app and choose the console’s HDMI – it finds the phone by itself. Keep English subtitles on in the game. Change the bar’s look in Subtitles on the phone, or while playing with OK on the TV remote. Leave the phone lying, ideally on a charger; its screen should stay on – ⚙ Settings → General → “Keep phone screen on”.",
        "hc7" to "7. When something doesn’t work",
        "hc7_qr" to "The page from the QR code won’t open on the phone: the phone must be on the same Wi-Fi (not mobile data).",
        "hc7_ps5" to "The console won’t connect: check Remote Play under the second user and that the console and this device are on the same network.",
        "hc7_net" to "The connection drops: on 2.4 GHz Wi-Fi the console’s controllers use the same band. Connect the console to the router with a cable, or switch this device to 5 GHz Wi-Fi.",
        "hc7_battery" to "Phone: the connection drops with the screen off – in ⚙ Settings → General turn on “Allow background use” (battery saving puts ReCaption to sleep).",
        "hc7_screen" to "Phone: with the screen off, translation slows down or nearly stops (Samsung reads subtitles up to 10× slower) – turn on ⚙ Settings → General → “Keep phone screen on” (the screen stays dimmed), ideally with the phone on a charger.",
        "hc7_other" to "The PS5 keeps showing “controller disconnected / account connected”: another device connects with the same second account (e.g. the PS Remote Play app). The second account should be used only by ReCaption.",
        "hc7_read" to "No subtitles appear: turn on ⚙ Settings → Experimental → Diagnostic mode to see what the app reads. A bug report sent to your phone helps too.",
        "hc8" to "8. Options in Settings",
        "hc9" to "9. More TVs or consoles",
        "hc9_text" to "•  Another PS5: Console page → “Pair another PS5”; switch between paired ones with the “Active PS5” row.\n•  PS5 and Xbox: ⚙ Settings → General → Console; pairing and sign-in stay saved.\n•  Two LG / Samsung TVs, one phone: the phone remembers the subtitle look and areas for each TV separately.\n•  Two Android TVs: install ReCaption on each; each has its own settings.",
        "hm_row" to "More TVs or consoles",
        "help_page" to "Guide page",
        "ls_other_device" to "Remote Play on the PS5 is now used by another device with the same account (e.g. the PS Remote Play app). ReCaption connects once it’s free.",
        "pv_stale" to "The preview is the last received frame – the picture isn’t arriving now:",
        "lg_launch" to "Start ReCaption on the TV",
        "tv_current" to "ReCaption is on the TV (version %s)",
        "lg_pass_other" to "Enter the Passphrase again",
        "vg_error" to "The video couldn’t be loaded. Check the internet connection or open the address in a browser:",
    ),
    Lang.PL to mapOf(
        "help_for" to "Instalacja dla",
        "hc1" to "1. Instalacja ReCaptionu",
        "hc1_android" to "ReCaption instaluje się na Android TV lub przystawce z Androidem podłączonej do telewizora. ReCaption.apk wgrywa się aplikacją Downloader – wystarczy wpisać w niej kod 8438934 (awaryjnie adres ze strony z instrukcją) albo z pendrive’a menedżerem plików. Kolejne wersje pojawią się same na Start.",
        "hc1_reader" to "Telewizory LG i Samsung same nie odczytają obrazu gry. Dlatego ReCaption działa w telefonie z Androidem (lub w przystawce): czyta obraz z konsoli, tłumaczy i wysyła gotowe napisy do aplikacji ReCaption w telewizorze. Na telefon trzeba pobrać i zainstalować ReCaption.apk (link jest na stronie z instrukcją).",
        "hc2" to "2. Przygotowanie konsoli",
        "hc2_ps" to "Na PS5 dodać 🔵 drugiego użytkownika z innym kontem PlayStation (za darmo). Aplikacja łączy się nim – gdyby użyła 🟢 konta do gry, konsola wyłączałaby kontroler podczas gry. Konto założone w internecie trzeba jeszcze dodać na PS5: ikona profilu → Przełącz użytkownika → Dodaj użytkownika i zalogować się kontem 🔵 (nie jako gość). U 🔵 drugiego użytkownika włączyć Ustawienia → System → Remote Play → Włącz Remote Play. Gra się potem normalnie na 🟢 koncie do gry.",
        "hc2_xbox" to "Na Xboxie włączyć Ustawienia → Urządzenia i połączenia → Funkcje zdalne, a tryb zasilania zostawić na „Uśpienie” (nie oszczędzanie energii). Potem w ReCaptionie na stronie Xbox zalogować konto Microsoft kodem na microsoft.com/link i wybrać Xboxa.",
        "hc3" to "3. Telewizor",
        "hc3_android" to "ReCaption rysuje pasek z tłumaczeniem nad obrazem gry. Trzeba na to zezwolić w ustawieniach telewizora: Ułatwienia dostępu → ReCaption → Włącz (ewentualnie „Wyświetlanie nad innymi aplikacjami”). Jeśli telewizor nie ma tego ekranu, da się to zrobić z komputera:",
        "hc3_lg" to "Na telewizor LG trafia aplikacja ReCaption (ekran z grą i paskiem). Wgrywa się ją z tego urządzenia przez tryb deweloperski LG – pomocnik prowadzi krok po kroku i sam odhacza gotowe kroki. Tryb deweloperski po czasie wygasa; Start ostrzeże na czas. To urządzenie musi być w tej samej sieci domowej co telewizor. Tryb deweloperski można przedłużyć na telewizorze w aplikacji Developer Mode (Extend) albo ReCaption przedłuża go raz dziennie z opcją ⚙ → Ogólne → Przedłużanie trybu deweloperskiego. Po wygaśnięciu ReCaption zniknie z telewizora i trzeba go wgrać ponownie. Da się to też zrobić z komputera narzędziem LG ares (opis na recaption.pages.dev/lg.html#pocitac folder webos).",
        "hc4" to "4. Język i jakość tłumaczenia",
        "hc4_text" to "Język tłumaczenia wybiera się w Napisach. Pod nim „Tłumacz z” to język napisów w grze (domyślnie angielski). Pakiet językowy pobiera się raz (ok. 30 MB), potem tłumaczenie działa offline i za darmo. Lepsze tłumaczenie przez DeepL (własny darmowy klucz) ustawia się w Napisy → Jakość tłumaczenia: na telewizorze wystarczy zeskanować jeden kod QR – strona w telefonie przeprowadzi przez rejestrację w DeepL, skopiowanie i wklejenie klucza.",
        "hc5" to "5. Parowanie konsoli",
        "hc5_text" to "Raz, według przewodnika na stronie Konsola: wybrać 🔵 drugie konto (dla ReCaptionu), zalogować je telefonem (kod QR), a na PS5 na tym samym użytkowniku włączyć Granie zdalne i wywołać ośmiocyfrowy numer. Jeśli wywoła go inny użytkownik, PS5 pokaże CE‑110032‑7. Potem przełączyć PS5 z powrotem na 🟢 konto do gry.",
        "hc5_xbox" to "Raz, na stronie Xbox (menu Konsola): Zaloguj konto Microsoft → w telefonie lub komputerze otworzyć microsoft.com/link (albo zeskanować kod QR), wpisać kod z ekranu i zalogować się kontem Microsoft, na którym gra się na Xboxie – drugie konto nie jest tu potrzebne. E-mail i hasło wpisuje się tylko na stronie Microsoftu, nie w ReCaptionie. Potem wybrać Xboxa, na którym się gra.",
        "hc6" to "6. Granie",
        "hc6_android" to "Na Start uruchomić tłumaczenie, poczekać na „obraz dociera” i przełączyć telewizor na HDMI konsoli. W grze muszą być włączone angielskie napisy. Wygląd i położenie paska zmienia się w Napisach.",
        "hc6_tv" to "Uruchomić tłumaczenie w ReCaptionie (telefon). W telewizorze otworzyć aplikację ReCaption i wybrać HDMI konsoli – sama znajdzie telefon. W grze muszą być włączone angielskie napisy. Wygląd paska zmienia się w Napisach w telefonie albo w trakcie gry przyciskiem OK na pilocie telewizora. Telefon może leżeć, najlepiej na ładowarce; ekran nie powinien gasnąć – ⚙ Ustawienia → Ogólne → „Nie wygaszać ekranu telefonu”.",
        "hc7" to "7. Gdy coś nie działa",
        "hc7_qr" to "Strona z kodu QR nie otwiera się w telefonie: telefon musi być w tej samej sieci Wi-Fi (nie na danych komórkowych).",
        "hc7_ps5" to "Konsola się nie łączy: sprawdzić Remote Play u drugiego użytkownika i czy konsola i to urządzenie są w tej samej sieci.",
        "hc7_net" to "Połączenie się zrywa: w Wi-Fi 2,4 GHz w tym samym paśmie działają kontrolery konsoli. Pomoże podłączenie konsoli do routera kablem albo przełączenie tego urządzenia na Wi-Fi 5 GHz.",
        "hc7_battery" to "Telefon: połączenie zrywa się przy wygaszonym ekranie – w ⚙ Ustawienia → Ogólne włączyć „Zezwól na działanie w tle” (oszczędzanie baterii usypia ReCaption).",
        "hc7_screen" to "Telefon: przy wyłączonym ekranie tłumaczenie zwalnia lub prawie staje (Samsung czyta napisy nawet 10× wolniej) – włączyć ⚙ Ustawienia → Ogólne → „Nie wygaszać ekranu telefonu” (ekran zostaje przyciemniony), najlepiej z telefonem na ładowarce.",
        "hc7_other" to "Na PS5 ciągle wyskakuje „kontroler odłączony / konto połączone”: z tym samym drugim kontem łączy się inne urządzenie (np. aplikacja PS Remote Play). Drugie konto ma służyć tylko ReCaptionowi.",
        "hc7_read" to "Napisy się nie pojawiają: włączyć ⚙ Ustawienia → Eksperymentalne → Tryb diagnostyczny – pokaże, co aplikacja czyta. Pomoże też zgłoszenie błędu wysłane do telefonu.",
        "hc8" to "8. Opcje w Ustawieniach",
        "hc9" to "9. Więcej telewizorów lub konsol",
        "hc9_text" to "•  Kolejna PS5: strona Konsola → „Sparuj kolejną PS5”; między sparowanymi przełącza wiersz „Aktywna PS5”.\n•  PS5 i Xbox: ⚙ Ustawienia → Ogólne → Konsola; parowanie i logowanie zostają zapisane.\n•  Dwa telewizory LG / Samsung, jeden telefon: telefon pamięta wygląd napisów i obszary dla każdego telewizora osobno.\n•  Dwa Android TV: ReCaption na każdym osobno, każdy ma własne ustawienia.",
        "hm_row" to "Więcej telewizorów lub konsol",
        "help_page" to "Strona z instrukcją",
        "ls_other_device" to "Remote Play na PS5 używa teraz inne urządzenie z tym samym kontem (np. aplikacja PS Remote Play). ReCaption połączy się, gdy je zwolni.",
        "pv_stale" to "Podgląd to ostatnia odebrana klatka – obraz teraz nie dociera:",
        "lg_launch" to "Uruchomić ReCaption w telewizorze",
        "tv_current" to "ReCaption jest w telewizorze (wersja %s)",
        "lg_pass_other" to "Wpisać Passphrase ponownie",
        "vg_error" to "Nie udało się wczytać wideo. Sprawdzić połączenie z internetem lub otworzyć adres w przeglądarce:",
    ),
    Lang.DE to mapOf(
        "help_for" to "Einrichtung für",
        "hc1" to "1. ReCaption installieren",
        "hc1_android" to "ReCaption gehört auf das Android TV oder die Android-Box am Fernseher. ReCaption.apk wird mit der App Downloader – dort genügt der Code 8438934 (ersatzweise die Adresse von der Anleitungsseite) oder per USB-Stick mit einem Dateimanager installiert. Neue Versionen werden danach auf Start angeboten.",
        "hc1_reader" to "LG- und Samsung-Fernseher können das Spielbild nicht selbst lesen. ReCaption läuft deshalb auf einem Android-Telefon (oder einer Box): Es liest das Bild der Konsole, übersetzt und schickt die fertigen Untertitel an die ReCaption-App auf dem Fernseher. ReCaption.apk aufs Telefon laden und installieren (Link auf der Anleitungsseite).",
        "hc2" to "2. Konsole vorbereiten",
        "hc2_ps" to "Auf der PS5 einen 🔵 zweiten Benutzer mit einem anderen PlayStation-Konto anlegen (kostenlos). Die App verbindet sich damit – mit dem 🟢 Spielkonto würde die Konsole beim Spielen den Controller trennen. Ein im Web angelegtes Konto muss noch auf der PS5 hinzugefügt werden: Profilsymbol → Benutzer wechseln → Benutzer hinzufügen und mit dem 🔵 Konto anmelden (nicht als Gast). Beim 🔵 zweiten Benutzer Einstellungen → System → Remote Play → Remote Play aktivieren einschalten. Gespielt wird dann wie gewohnt mit dem 🟢 Spielkonto.",
        "hc2_xbox" to "Auf der Xbox Einstellungen → Geräte & Verbindungen → Remotefunktionen einschalten und den Energiemodus auf „Ruhezustand“ lassen (nicht Energiesparen). Dann in ReCaption auf der Seite Xbox ein Microsoft-Konto mit dem Code auf microsoft.com/link anmelden und die Xbox wählen.",
        "hc3" to "3. Fernseher",
        "hc3_android" to "ReCaption zeichnet den Übersetzungsbalken über das Spielbild. Das wird in den Fernseheinstellungen erlaubt: Bedienungshilfen → ReCaption → Ein (oder „Über anderen Apps einblenden“). Fehlt diese Seite, geht es auch vom Computer:",
        "hc3_lg" to "Auf den LG-Fernseher kommt die App ReCaption (Bild mit Spiel und Balken). Sie wird von diesem Gerät über den LG-Entwicklermodus installiert – der Helfer führt Schritt für Schritt und hakt erledigte Schritte selbst ab. Der Entwicklermodus läuft nach einiger Zeit ab; Start warnt rechtzeitig. Dieses Gerät muss im selben Heimnetz sein wie der Fernseher. Verlängern lässt sich der Entwicklermodus am Fernseher in der App Developer Mode (Extend), oder ReCaption verlängert ihn einmal täglich mit der Option ⚙ → Allgemein → Entwicklermodus verlängern. Läuft er ab, verschwindet ReCaption vom Fernseher und wird neu installiert. Es geht auch vom Computer mit dem LG-Werkzeug ares (Anleitung auf recaption.pages.dev/lg.html#pocitac Ordner webos).",
        "hc4" to "4. Sprache und Übersetzungsqualität",
        "hc4_text" to "Die Übersetzungssprache wird unter Untertitel gewählt. Darunter ist „Übersetzen aus“ die Sprache der Untertitel im Spiel (standardmäßig Englisch). Das Sprachpaket wird einmal geladen (ca. 30 MB), danach wird offline und kostenlos übersetzt. Bessere Übersetzung mit DeepL (eigener kostenloser Schlüssel) wird unter Untertitel → Übersetzungsqualität eingerichtet: am Fernseher genügt ein QR-Code – die Seite auf dem Handy führt durch Registrierung bei DeepL, Kopieren und Einfügen des Schlüssels.",
        "hc5" to "5. Konsole koppeln",
        "hc5_text" to "Einmal, mit der Anleitung auf der Seite Konsole: 🔵 zweites Konto (für ReCaption) wählen, mit dem Handy anmelden (QR-Code), dann auf der PS5 unter demselben Benutzer Remote Play aktivieren und die achtstellige Zahl anzeigen lassen. Zeigt sie ein anderer Benutzer an, meldet die PS5 CE‑110032‑7. Danach auf der PS5 zurück zum 🟢 Spielkonto wechseln.",
        "hc5_xbox" to "Einmal, auf der Seite Xbox (Menü Konsole): Microsoft-Konto anmelden → auf dem Handy oder Computer microsoft.com/link öffnen (oder den QR-Code scannen), den angezeigten Code eingeben und mit dem Microsoft-Konto anmelden, mit dem auf der Xbox gespielt wird – ein zweites Konto ist hier nicht nötig. E-Mail und Passwort nur auf der Seite von Microsoft eingeben, nicht in ReCaption. Dann die Xbox wählen, auf der gespielt wird.",
        "hc6" to "6. Spielen",
        "hc6_android" to "Auf Start die Übersetzung starten, auf „Bild kommt an“ warten und den Fernseher auf den HDMI-Eingang der Konsole schalten. Englische Untertitel im Spiel einschalten. Aussehen und Position des Balkens werden unter Untertitel geändert.",
        "hc6_tv" to "Die Übersetzung in ReCaption (Telefon) starten. Auf dem Fernseher die App ReCaption öffnen und den HDMI-Eingang der Konsole wählen – sie findet das Telefon selbst. Englische Untertitel im Spiel einschalten. Das Aussehen des Balkens wird unter Untertitel im Telefon oder beim Spielen mit OK auf der Fernbedienung geändert. Das Telefon kann liegen bleiben, am besten am Ladegerät; das Display sollte anbleiben – ⚙ Einstellungen → Allgemein → „Telefonbildschirm anlassen“.",
        "hc7" to "7. Wenn etwas nicht geht",
        "hc7_qr" to "Die Seite vom QR-Code öffnet sich nicht: Das Telefon muss im selben WLAN sein (nicht mobile Daten).",
        "hc7_ps5" to "Die Konsole verbindet sich nicht: Remote Play beim zweiten Benutzer prüfen und ob Konsole und dieses Gerät im selben Netz sind.",
        "hc7_net" to "Die Verbindung bricht ab: Im 2,4-GHz-WLAN funken auch die Controller der Konsole. Abhilfe: die Konsole per Kabel an den Router anschließen oder dieses Gerät auf 5-GHz-WLAN schalten.",
        "hc7_battery" to "Telefon: Die Verbindung bricht bei ausgeschaltetem Display ab – unter ⚙ Einstellungen → Allgemein „Hintergrundnutzung erlauben“ einschalten (der Energiesparmodus legt ReCaption schlafen).",
        "hc7_screen" to "Handy: Bei ausgeschaltetem Bildschirm wird die Übersetzung langsam oder bleibt fast stehen (Samsung liest Untertitel bis zu 10× langsamer) – ⚙ Einstellungen → Allgemein → „Telefonbildschirm anlassen“ einschalten (der Bildschirm bleibt gedimmt), am besten mit dem Handy am Ladegerät.",
        "hc7_other" to "Auf der PS5 erscheint immer wieder „Controller getrennt / Konto verbunden“: Ein anderes Gerät verbindet sich mit demselben zweiten Konto (z. B. die App PS Remote Play). Das zweite Konto soll nur ReCaption dienen.",
        "hc7_read" to "Es erscheinen keine Untertitel: ⚙ Einstellungen → Experimentell → Diagnosemodus einschalten – er zeigt, was die App liest. Auch ein ans Telefon gesendeter Fehlerbericht hilft.",
        "hc8" to "8. Optionen in den Einstellungen",
        "hc9" to "9. Mehrere Fernseher oder Konsolen",
        "hc9_text" to "•  Weitere PS5: Seite Konsole → „Weitere PS5 koppeln“; zwischen gekoppelten wechselt die Zeile „Aktive PS5“.\n•  PS5 und Xbox: ⚙ Einstellungen → Allgemein → Konsole; Kopplung und Anmeldung bleiben gespeichert.\n•  Zwei LG-/Samsung-Fernseher, ein Telefon: Das Telefon merkt sich Untertitel-Aussehen und Bereiche für jeden Fernseher einzeln.\n•  Zwei Android TVs: ReCaption auf jedem einzeln, jeder hat eigene Einstellungen.",
        "hm_row" to "Mehrere Fernseher oder Konsolen",
        "help_page" to "Anleitungsseite",
        "ls_other_device" to "Remote Play auf der PS5 nutzt gerade ein anderes Gerät mit demselben Konto (z. B. die App PS Remote Play). ReCaption verbindet sich, sobald es frei ist.",
        "pv_stale" to "Die Vorschau ist das zuletzt empfangene Bild – gerade kommt kein Bild an:",
        "lg_launch" to "ReCaption auf dem Fernseher starten",
        "tv_current" to "ReCaption ist auf dem Fernseher (Version %s)",
        "lg_pass_other" to "Passphrase erneut eingeben",
        "vg_error" to "Das Video konnte nicht geladen werden. Internetverbindung prüfen oder die Adresse im Browser öffnen:",
    ),
    Lang.HU to mapOf(
        "help_for" to "Telepítés ehhez",
        "hc1" to "1. A ReCaption telepítése",
        "hc1_android" to "A ReCaption a tévére kötött Android TV-re vagy androidos boxra kerül. A ReCaption.apk a Downloader alkalmazással – abban elég megadni a 8438934 kódot (tartalékként az útmutató oldalán lévő címet) vagy pendrive-ról fájlkezelővel telepíthető. A későbbi verziókat a Kezdőlap magától felajánlja.",
        "hc1_reader" to "Az LG és Samsung tévék maguk nem tudják olvasni a játék képét. Ezért a ReCaption androidos telefonon (vagy boxon) fut: olvassa a konzol képét, fordít, és a kész feliratokat elküldi a tévén futó ReCaption alkalmazásnak. A ReCaption.apk-t le kell tölteni a telefonra és telepíteni (a link az útmutató oldalán van).",
        "hc2" to "2. A konzol előkészítése",
        "hc2_ps" to "A PS5-ön létre kell hozni egy 🔵 második felhasználót másik PlayStation-fiókkal (ingyenes). Az alkalmazás ezzel csatlakozik – ha a 🟢 játékfiókkal tenné, a konzol játék közben lekapcsolná a kontrollert. A weben létrehozott fiókot a PS5-ön még hozzá kell adni: profilikon → Felhasználóváltás → Felhasználó hozzáadása, majd bejelentkezés a 🔵 fiókkal (nem vendégként). A 🔵 második felhasználónál be kell kapcsolni: Beállítások → Rendszer → Távoli játék → Távoli játék engedélyezése. Utána a játék a 🟢 játékfiókkal megy, mint eddig.",
        "hc2_xbox" to "Az Xboxon be kell kapcsolni: Beállítások → Eszközök és kapcsolatok → Távoli funkciók, az energiamód maradjon „Alvó” (ne energiatakarékos). Utána a ReCaption Xbox oldalán bejelentkezés Microsoft-fiókkal a microsoft.com/link kóddal, majd az Xbox kiválasztása.",
        "hc3" to "3. Tévé",
        "hc3_android" to "A ReCaption a fordítási sávot a játék képe fölé rajzolja. Engedélyezni kell a tévé beállításaiban: Kisegítő lehetőségek → ReCaption → Be (vagy „Megjelenítés más alkalmazások felett”). Ha a tévén nincs ilyen oldal, számítógépről is engedélyezhető:",
        "hc3_lg" to "Az LG tévére a ReCaption alkalmazás kerül (képernyő a játékkal és a sávval). Erről az eszközről települ az LG fejlesztői módon át – a segéd lépésről lépésre vezet, és a kész lépéseket maga pipálja ki. A fejlesztői mód idővel lejár; a Kezdőlap időben szól. Ennek az eszköznek ugyanazon az otthoni hálózaton kell lennie, mint a tévének. A fejlesztői módot a tévén, a Developer Mode alkalmazásban lehet meghosszabbítani (Extend), vagy a ReCaption naponta egyszer meghosszabbítja a ⚙ → Általános → Fejlesztői mód meghosszabbítása beállítással. Ha lejár, a ReCaption eltűnik a tévéről, és újra kell telepíteni. Számítógépről is telepíthető az LG ares eszközével (leírás: recaption.pages.dev/lg.html#pocitac webos mappa).",
        "hc4" to "4. Nyelv és fordítási minőség",
        "hc4_text" to "A fordítás nyelve a Feliratokban választható ki. Alatta a „Forrásnyelv” a játék feliratainak nyelve (alapból angol). A nyelvi csomag egyszer töltődik le (kb. 30 MB), utána a fordítás offline és ingyenes. Jobb fordítás DeepL-lel (saját ingyenes kulcs): Feliratok → Fordítás minősége. A tévén elég egy QR-kódot beolvasni – a telefonos oldal végigvezet a DeepL-regisztráción, a kulcs másolásán és beillesztésén.",
        "hc5" to "5. A konzol párosítása",
        "hc5_text" to "Egyszer, a Konzol oldal útmutatója szerint: a 🔵 második fiók kiválasztása (a ReCaptionhoz), bejelentkezés vele telefonon (QR-kód), majd a PS5-ön ugyanazzal a felhasználóval a Távoli játék bekapcsolása és a nyolcjegyű szám lekérése. Ha más felhasználó kéri le, a PS5 CE‑110032‑7 hibát jelez. Utána a PS5-ön vissza kell váltani a 🟢 játékfiókra.",
        "hc5_xbox" to "Egyszer, az Xbox oldalon (Konzol menü): Microsoft-fiók bejelentkeztetése → telefonon vagy számítógépen a microsoft.com/link megnyitása (vagy a QR-kód beolvasása), a képernyőn látható kód beírása és bejelentkezés az Xboxon játékhoz használt Microsoft-fiókkal – második fiók itt nem kell. Az e-mail-cím és a jelszó csak a Microsoft oldalára kerül, a ReCaptionba nem. Utána annak az Xboxnak a kiválasztása, amelyen a játék megy.",
        "hc6" to "6. Játék",
        "hc6_android" to "A Kezdőlapon el kell indítani a fordítást, megvárni, hogy „a kép érkezik”, és a tévét a konzol HDMI-bemenetére kapcsolni. A játékban legyen bekapcsolva az angol felirat. A sáv kinézete és helye a Feliratokban állítható.",
        "hc6_tv" to "A fordítást a ReCaptionban (telefon) kell elindítani. A tévén meg kell nyitni a ReCaption alkalmazást, és a konzol HDMI-bemenetét választani – a telefont maga megtalálja. A játékban legyen bekapcsolva az angol felirat. A sáv kinézete a telefonon a Feliratokban, vagy játék közben a tévé távirányítójának OK gombjával módosítható. A telefon maradhat fekve, legjobb töltőn; a kijelzője ne kapcsoljon ki – ⚙ Beállítások → Általános → „Telefon kijelzője maradjon bekapcsolva”.",
        "hc7" to "7. Ha valami nem működik",
        "hc7_qr" to "A QR-kód oldala nem nyílik meg a telefonon: a telefonnak ugyanazon a Wi-Fi-n kell lennie (nem mobiladaton).",
        "hc7_ps5" to "A konzol nem csatlakozik: érdemes ellenőrizni a Remote Playt a második felhasználónál, és hogy a konzol és ez az eszköz ugyanazon a hálózaton van-e.",
        "hc7_net" to "A kapcsolat megszakad: 2,4 GHz-es Wi-Fi-n ugyanabban a sávban működnek a konzol kontrollerei is. Segít, ha a konzol kábellel csatlakozik a routerhez, vagy ez az eszköz 5 GHz-es Wi-Fi-re vált.",
        "hc7_battery" to "Telefon: a kapcsolat kikapcsolt kijelzőnél megszakad – a ⚙ Beállítások → Általános alatt be kell kapcsolni a „Háttérben futás engedélyezése” lehetőséget (az akkumulátorkímélés elaltatja a ReCaptiont).",
        "hc7_screen" to "Telefon: kikapcsolt kijelzőnél a fordítás lelassul vagy szinte leáll (a Samsung akár 10× lassabban olvassa a feliratot) – a ⚙ Beállítások → Általános → „Telefon kijelzője maradjon bekapcsolva” bekapcsolása (a kijelző elsötétítve marad), a telefon legjobb, ha töltőn van.",
        "hc7_other" to "A PS5-ön folyton „kontroller leválasztva / fiók csatlakoztatva” jelenik meg: ugyanazzal a második fiókkal másik eszköz csatlakozik (pl. a PS Remote Play alkalmazás). A második fiók csak a ReCaptiont szolgálja.",
        "hc7_read" to "Nem jelennek meg feliratok: a ⚙ Beállítások → Kísérleti → Diagnosztikai mód megmutatja, mit olvas az alkalmazás. Segít a telefonra küldött hibajelentés is.",
        "hc8" to "8. A Beállítások lehetőségei",
        "hc9" to "9. Több tévé vagy konzol",
        "hc9_text" to "•  Másik PS5: Konzol oldal → „Másik PS5 párosítása”; a párosítottak között az „Aktív PS5” sor vált.\n•  PS5 és Xbox: ⚙ Beállítások → Általános → Konzol; a párosítás és a bejelentkezés megmarad.\n•  Két LG / Samsung tévé, egy telefon: a telefon minden tévéhez külön megjegyzi a felirat kinézetét és területeit.\n•  Két Android TV: a ReCaption mindegyikre külön, mindegyiknek saját beállításai vannak.",
        "hm_row" to "Több tévé vagy konzol",
        "help_page" to "Útmutató oldal",
        "ls_other_device" to "A PS5 Remote Playét most egy másik eszköz használja ugyanazzal a fiókkal (pl. a PS Remote Play alkalmazás). A ReCaption csatlakozik, ha felszabadul.",
        "pv_stale" to "Az előnézet az utoljára kapott kép – most nem érkezik kép:",
        "lg_launch" to "ReCaption indítása a tévén",
        "tv_current" to "A ReCaption a tévén van (%s verzió)",
        "lg_pass_other" to "Passphrase újbóli megadása",
        "vg_error" to "A videó nem töltődött be. Az internetkapcsolat ellenőrzése, vagy a cím megnyitása böngészőben:",
    ),
    Lang.UK to mapOf(
        "help_for" to "Встановлення для",
        "hc1" to "1. Встановлення ReCaption",
        "hc1_android" to "ReCaption встановлюється на Android TV або Android-приставку, підключену до телевізора. Завантажити ReCaption.apk можна застосунком Downloader – у ньому достатньо ввести код 8438934 (запасний варіант – адреса зі сторінки з інструкцією) або з флешки файловим менеджером. Наступні версії запропонуються самі на Головній.",
        "hc1_reader" to "Телевізори LG і Samsung не можуть самі читати зображення гри. Тому ReCaption працює на Android-телефоні (або приставці): читає зображення з консолі, перекладає й надсилає готові субтитри в застосунок ReCaption на телевізорі. ReCaption.apk треба завантажити в телефон і встановити (посилання на сторінці з інструкцією).",
        "hc2" to "2. Підготовка консолі",
        "hc2_ps" to "На PS5 додати 🔵 другого користувача з іншим обліковим записом PlayStation (безкоштовно). Застосунок підключається через нього – якби він використав 🟢 ігровий запис, консоль вимикала б контролер під час гри. Запис, створений на сайті, треба ще додати на PS5: значок профілю → Змінити користувача → Додати користувача й увійти 🔵 записом (не як гість). У 🔵 другого користувача увімкнути Налаштування → Система → Дистанційна гра → Дозволити дистанційну гру. Грати потім як завжди під 🟢 ігровим записом.",
        "hc2_xbox" to "На Xbox увімкнути Налаштування → Пристрої та підключення → Віддалені функції, а режим живлення залишити «Сон» (не енергозбереження). Потім у ReCaption на сторінці Xbox увійти з обліковим записом Microsoft кодом на microsoft.com/link і вибрати Xbox.",
        "hc3" to "3. Телевізор",
        "hc3_android" to "ReCaption малює смугу з перекладом поверх зображення гри. Це дозволяється в налаштуваннях телевізора: Спеціальні можливості → ReCaption → Увімкнути (або «Показ поверх інших застосунків»). Якщо такого екрана немає, це можна дозволити з комп’ютера:",
        "hc3_lg" to "На телевізор LG ставиться застосунок ReCaption (екран з грою та смугою). Він встановлюється з цього пристрою через режим розробника LG – помічник проведе крок за кроком і сам позначить виконані кроки. Режим розробника з часом спливає; Головна вчасно попередить. Цей пристрій має бути в тій самій домашній мережі, що й телевізор. Подовжити режим розробника можна на телевізорі в застосунку Developer Mode (Extend), або ReCaption подовжує його раз на день з параметром ⚙ → Загальні → Подовжувати режим розробника. Коли він спливе, ReCaption зникне з телевізора і його треба встановити знову. Встановити можна й з комп’ютера інструментом LG ares (опис на recaption.pages.dev/lg.html#pocitac тека webos).",
        "hc4" to "4. Мова та якість перекладу",
        "hc4_text" to "Мова перекладу вибирається в Субтитрах. Під ним «Перекладати з» – мова субтитрів у грі (типово англійська). Мовний пакет завантажується один раз (близько 30 МБ), далі переклад офлайн і безкоштовно. Кращий переклад через DeepL (власний безкоштовний ключ) налаштовується в Субтитри → Якість перекладу: на телевізорі досить відсканувати один QR-код – сторінка в телефоні проведе через реєстрацію в DeepL, копіювання й вставлення ключа.",
        "hc5" to "5. З’єднання консолі",
        "hc5_text" to "Один раз, за інструкцією на сторінці Консоль: вибрати 🔵 другий запис (для ReCaption), увійти ним через телефон (QR-код), а на PS5 під тим самим користувачем увімкнути дистанційну гру й викликати восьмизначне число. Якщо його викличе інший користувач, PS5 покаже CE‑110032‑7. Потім на PS5 перемкнутися назад на 🟢 ігровий запис.",
        "hc5_xbox" to "Один раз, на сторінці Xbox (меню Консоль): Увійти з обліковим записом Microsoft → на телефоні чи комп’ютері відкрити microsoft.com/link (або відсканувати QR-код), ввести код з екрана й увійти тим записом Microsoft, яким грають на Xbox – другий запис тут не потрібен. Електронну пошту й пароль вводять лише на сторінці Microsoft, не в ReCaption. Потім вибрати Xbox, на якому грають.",
        "hc6" to "6. Гра",
        "hc6_android" to "На Головній запустити переклад, дочекатися «зображення надходить» і перемкнути телевізор на HDMI консолі. У грі мають бути увімкнені англійські субтитри. Вигляд і положення смуги змінюються в Субтитрах.",
        "hc6_tv" to "Запустити переклад у ReCaption (телефон). На телевізорі відкрити застосунок ReCaption і вибрати HDMI консолі – телефон він знайде сам. У грі мають бути увімкнені англійські субтитри. Вигляд смуги змінюється в Субтитрах на телефоні або під час гри кнопкою OK на пульті телевізора. Телефон може лежати, найкраще на зарядці; екран не має згасати – ⚙ Налаштування → Загальні → «Не вимикати екран телефона».",
        "hc7" to "7. Коли щось не працює",
        "hc7_qr" to "Сторінка з QR-коду не відкривається в телефоні: телефон має бути в тій самій Wi-Fi (не на мобільних даних).",
        "hc7_ps5" to "Консоль не підключається: перевірити Remote Play у другого користувача і чи консоль та цей пристрій в одній мережі.",
        "hc7_net" to "З’єднання обривається: у Wi-Fi 2,4 ГГц у тому ж діапазоні працюють контролери консолі. Допоможе під’єднати консоль до роутера кабелем або перемкнути цей пристрій на Wi-Fi 5 ГГц.",
        "hc7_battery" to "Телефон: з’єднання обривається при вимкненому екрані – у ⚙ Налаштування → Загальні увімкнути «Дозволити роботу у фоні» (економія батареї приспає ReCaption).",
        "hc7_screen" to "Телефон: коли екран вимкнено, переклад сповільнюється або майже зупиняється (Samsung читає субтитри до 10× повільніше) – увімкнути ⚙ Налаштування → Загальні → «Не вимикати екран телефона» (екран лишиться притьмареним), найкраще з телефоном на зарядці.",
        "hc7_other" to "На PS5 постійно з’являється «контролер відключено / запис підключено»: з тим самим другим записом підключається інший пристрій (напр. застосунок PS Remote Play). Другий запис має служити лише ReCaption.",
        "hc7_read" to "Субтитри не з’являються: увімкнути ⚙ Налаштування → Експериментальне → Діагностичний режим – він покаже, що читає застосунок. Допоможе й звіт про помилку, надісланий у телефон.",
        "hc8" to "8. Параметри в Налаштуваннях",
        "hc9" to "9. Кілька телевізорів або консолей",
        "hc9_text" to "•  Ще одна PS5: сторінка Консоль → «Під’єднати ще одну PS5»; між під’єднаними перемикає рядок «Активна PS5».\n•  PS5 і Xbox: ⚙ Налаштування → Загальні → Консоль; під’єднання і вхід зберігаються.\n•  Два телевізори LG / Samsung, один телефон: телефон пам’ятає вигляд субтитрів і області для кожного телевізора окремо.\n•  Два Android TV: ReCaption на кожен окремо, кожен має власні налаштування.",
        "hm_row" to "Кілька телевізорів або консолей",
        "help_page" to "Сторінка з інструкцією",
        "ls_other_device" to "Remote Play на PS5 зараз використовує інший пристрій з тим самим записом (напр. застосунок PS Remote Play). ReCaption підключиться, коли його звільнять.",
        "pv_stale" to "Попередній перегляд – останній отриманий кадр, зараз зображення не надходить:",
        "lg_launch" to "Запустити ReCaption на телевізорі",
        "tv_current" to "ReCaption є на телевізорі (версія %s)",
        "lg_pass_other" to "Ввести Passphrase знову",
        "vg_error" to "Не вдалося завантажити відео. Перевірити підключення до інтернету або відкрити адресу в браузері:",
    ),
    Lang.ES to mapOf(
        "help_for" to "Instalación para",
        "hc1" to "1. Instalar ReCaption",
        "hc1_android" to "ReCaption se instala en el Android TV o la caja Android conectada al televisor. ReCaption.apk se instala con la app Downloader – basta con introducir en ella el código 8438934 (como alternativa, la dirección de la página de la guía) o desde un USB con un gestor de archivos. Las versiones nuevas se ofrecen solas en Inicio.",
        "hc1_reader" to "Los televisores LG y Samsung no pueden leer la imagen del juego por sí mismos. Por eso ReCaption funciona en un teléfono Android (o una caja): lee la imagen de la consola, traduce y envía los subtítulos terminados a la app ReCaption del televisor. Descargar ReCaption.apk en el teléfono e instalarlo (el enlace está en la página de la guía).",
        "hc2" to "2. Preparar la consola",
        "hc2_ps" to "En la PS5, añadir un 🔵 segundo usuario con otra cuenta de PlayStation (gratis). La app se conecta con él: si usara la 🟢 cuenta de juego, la consola apagaría el mando durante la partida. Una cuenta creada en la web hay que añadirla además en la PS5: icono del perfil → Cambiar de usuario → Añadir usuario e iniciar sesión con la 🔵 cuenta (no como invitado). Con el 🔵 segundo usuario, activar Ajustes → Sistema → Uso a distancia → Activar el Uso a distancia. Luego se juega como siempre con la 🟢 cuenta de juego.",
        "hc2_xbox" to "En la Xbox, activar Configuración → Dispositivos y conexiones → Funciones remotas y dejar el modo de energía en «Suspensión» (no ahorro de energía). Luego, en la página Xbox de ReCaption, iniciar sesión con una cuenta Microsoft con el código en microsoft.com/link y elegir la Xbox.",
        "hc3" to "3. Televisor",
        "hc3_android" to "ReCaption dibuja la barra de traducción sobre la imagen del juego. Se permite en los ajustes del televisor: Accesibilidad → ReCaption → Activar (o «Mostrar sobre otras apps»). Si el televisor no tiene esa pantalla, se puede permitir desde un ordenador:",
        "hc3_lg" to "En el televisor LG va la app ReCaption (pantalla con el juego y la barra). Se instala desde este dispositivo mediante el modo desarrollador de LG: el asistente guía paso a paso y marca solo los pasos hechos. El modo desarrollador caduca con el tiempo; Inicio avisa a tiempo. Este dispositivo debe estar en la misma red doméstica que el televisor. El modo desarrollador se amplía en el televisor, en la app Developer Mode (Extend), o ReCaption lo prolonga una vez al día con la opción ⚙ → General → Prolongar el modo desarrollador. Si caduca, ReCaption desaparece del televisor y hay que instalarlo de nuevo. También se puede instalar desde un ordenador con la herramienta de LG ares (instrucciones en recaption.pages.dev/lg.html#pocitac carpeta webos).",
        "hc4" to "4. Idioma y calidad de la traducción",
        "hc4_text" to "El idioma de la traducción se elige en Subtítulos. Debajo, «Traducir desde» es el idioma de los subtítulos del juego (inglés por defecto). El paquete de idioma se descarga una vez (unos 30 MB) y luego la traducción es sin conexión y gratis. Una traducción mejor con DeepL (clave propia gratuita) se configura en Subtítulos → Calidad de la traducción: en la tele basta con escanear un código QR: la página en el móvil guía por el registro en DeepL y por copiar y pegar la clave.",
        "hc5" to "5. Vincular la consola",
        "hc5_text" to "Una vez, siguiendo la guía de la página Consola: elegir la 🔵 segunda cuenta (para ReCaption), iniciar sesión con el móvil (código QR) y en la PS5, con ese mismo usuario, activar Uso a distancia y pedir el número de ocho cifras. Si lo pide otro usuario, la PS5 muestra CE‑110032‑7. Después, volver en la PS5 a la 🟢 cuenta de juego.",
        "hc5_xbox" to "Una vez, en la página Xbox (menú Consola): Iniciar sesión con una cuenta Microsoft → en el móvil o el ordenador abrir microsoft.com/link (o escanear el código QR), introducir el código de la pantalla e iniciar sesión con la cuenta Microsoft con la que se juega en la Xbox; aquí no hace falta una segunda cuenta. El correo y la contraseña se escriben solo en la página de Microsoft, no en ReCaption. Después, elegir la Xbox en la que se juega.",
        "hc6" to "6. Jugar",
        "hc6_android" to "En Inicio, iniciar la traducción, esperar a «la imagen llega» y cambiar el televisor al HDMI de la consola. Los subtítulos en inglés del juego deben estar activados. El aspecto y la posición de la barra se cambian en Subtítulos.",
        "hc6_tv" to "Iniciar la traducción en ReCaption (teléfono). En el televisor, abrir la app ReCaption y elegir el HDMI de la consola: encuentra el teléfono sola. Los subtítulos en inglés del juego deben estar activados. El aspecto de la barra se cambia en Subtítulos en el teléfono o, durante la partida, con OK en el mando del televisor. El teléfono puede quedarse quieto, mejor cargando; la pantalla no debe apagarse – ⚙ Ajustes → General → «No apagar la pantalla del teléfono».",
        "hc7" to "7. Cuando algo no funciona",
        "hc7_qr" to "La página del código QR no se abre en el teléfono: el teléfono debe estar en la misma Wi-Fi (no con datos móviles).",
        "hc7_ps5" to "La consola no se conecta: comprobar el Juego remoto del segundo usuario y que la consola y este dispositivo estén en la misma red.",
        "hc7_net" to "La conexión se corta: en Wi-Fi de 2,4 GHz los mandos de la consola usan la misma banda. Ayuda conectar la consola al router por cable o pasar este dispositivo a Wi-Fi de 5 GHz.",
        "hc7_battery" to "Teléfono: la conexión se corta con la pantalla apagada; en ⚙ Ajustes → General activar «Permitir uso en segundo plano» (el ahorro de batería suspende ReCaption).",
        "hc7_screen" to "Teléfono: con la pantalla apagada la traducción se ralentiza o casi se detiene (Samsung lee los subtítulos hasta 10× más despacio) – activar ⚙ Ajustes → General → «No apagar la pantalla del teléfono» (la pantalla queda atenuada), idealmente con el teléfono cargando.",
        "hc7_other" to "En la PS5 aparece una y otra vez «mando desconectado / cuenta conectada»: otro dispositivo se conecta con la misma segunda cuenta (p. ej. la app PS Remote Play). La segunda cuenta debe ser solo para ReCaption.",
        "hc7_read" to "No aparecen subtítulos: activar ⚙ Ajustes → Experimental → Modo de diagnóstico para ver qué lee la app. También ayuda un informe de error enviado al teléfono.",
        "hc8" to "8. Opciones de Ajustes",
        "hc9" to "9. Varios televisores o consolas",
        "hc9_text" to "•  Otra PS5: página Consola → «Vincular otra PS5»; entre las vinculadas se cambia con la fila «PS5 activa».\n•  PS5 y Xbox: ⚙ Ajustes → General → Consola; la vinculación y el inicio de sesión se conservan.\n•  Dos televisores LG / Samsung, un teléfono: el teléfono recuerda el aspecto de los subtítulos y las zonas de cada televisor por separado.\n•  Dos Android TV: ReCaption en cada uno por separado; cada uno tiene sus propios ajustes.",
        "hm_row" to "Varios televisores o consolas",
        "help_page" to "Página de la guía",
        "ls_other_device" to "El Juego remoto de la PS5 lo usa ahora otro dispositivo con la misma cuenta (p. ej. la app PS Remote Play). ReCaption se conectará cuando quede libre.",
        "pv_stale" to "La vista previa es el último fotograma recibido; ahora no llega imagen:",
        "lg_launch" to "Iniciar ReCaption en el televisor",
        "tv_current" to "ReCaption está en el televisor (versión %s)",
        "lg_pass_other" to "Introducir de nuevo la Passphrase",
        "vg_error" to "No se pudo cargar el vídeo. Comprobar la conexión a internet o abrir la dirección en un navegador:",
    ),
    Lang.FR to mapOf(
        "help_for" to "Installation pour",
        "hc1" to "1. Installer ReCaption",
        "hc1_android" to "ReCaption s’installe sur l’Android TV ou le boîtier Android branché au téléviseur. ReCaption.apk s’installe avec l’appli Downloader – il suffit d’y saisir le code 8438934 (à défaut, l’adresse de la page du guide) ou depuis une clé USB avec un gestionnaire de fichiers. Les versions suivantes sont proposées toutes seules sur Accueil.",
        "hc1_reader" to "Les téléviseurs LG et Samsung ne savent pas lire eux-mêmes l’image du jeu. ReCaption tourne donc sur un téléphone Android (ou un boîtier) : il lit l’image de la console, traduit et envoie les sous-titres prêts à l’appli ReCaption du téléviseur. Télécharger ReCaption.apk sur le téléphone et l’installer (le lien est sur la page du guide).",
        "hc2" to "2. Préparer la console",
        "hc2_ps" to "Sur la PS5, ajouter un 🔵 deuxième utilisateur avec un autre compte PlayStation (gratuit). L’appli se connecte avec lui : avec le 🟢 compte de jeu, la console déconnecterait la manette pendant la partie. Un compte créé sur le web doit encore être ajouté sur la PS5 : icône du profil → Changer d’utilisateur → Ajouter un utilisateur, puis se connecter avec le 🔵 compte (pas en invité). Pour le 🔵 deuxième utilisateur, activer Paramètres → Système → Lecture à distance → Activer Lecture à distance. On joue ensuite normalement avec le 🟢 compte de jeu.",
        "hc2_xbox" to "Sur la Xbox, activer Paramètres → Appareils et connexions → Fonctionnalités à distance et garder le mode d’alimentation sur « Veille » (pas économie d’énergie). Puis, sur la page Xbox de ReCaption, connecter un compte Microsoft avec le code sur microsoft.com/link et choisir la Xbox.",
        "hc3" to "3. Téléviseur",
        "hc3_android" to "ReCaption dessine le bandeau de traduction par-dessus l’image du jeu. À autoriser dans les réglages du téléviseur : Accessibilité → ReCaption → Activer (ou « Afficher par-dessus les autres applis »). Si le téléviseur n’a pas cet écran, on peut l’autoriser depuis un ordinateur :",
        "hc3_lg" to "Sur le téléviseur LG va l’appli ReCaption (écran avec le jeu et le bandeau). Elle s’installe depuis cet appareil via le mode développeur LG : l’assistant guide pas à pas et coche tout seul les étapes faites. Le mode développeur expire au bout d’un moment ; Accueil prévient à temps. Cet appareil doit être sur le même réseau domestique que le téléviseur. Le mode développeur se prolonge sur le téléviseur, dans l’app Developer Mode (Extend), ou ReCaption le prolonge une fois par jour avec l’option ⚙ → Général → Prolonger le mode développeur. S’il expire, ReCaption disparaît du téléviseur et doit être réinstallé. L’installation est aussi possible depuis un ordinateur avec l’outil LG ares (voir recaption.pages.dev/lg.html#pocitac dossier webos).",
        "hc4" to "4. Langue et qualité de traduction",
        "hc4_text" to "La langue de traduction se choisit dans Sous-titres. Juste en dessous, « Traduire depuis » est la langue des sous-titres du jeu (anglais par défaut). Le pack de langue se télécharge une fois (environ 30 Mo), ensuite la traduction est hors ligne et gratuite. Une meilleure traduction avec DeepL (clé personnelle gratuite) se règle dans Sous-titres → Qualité de la traduction : sur la télé, un seul QR code à scanner – la page sur le téléphone guide pour l’inscription chez DeepL, la copie et le collage de la clé.",
        "hc5" to "5. Associer la console",
        "hc5_text" to "Une fois, avec le guide de la page Console : choisir le 🔵 second compte (pour ReCaption), le connecter avec le téléphone (QR code), puis sur la PS5, sous le même utilisateur, activer la Lecture à distance et demander le nombre à huit chiffres. Si un autre utilisateur le demande, la PS5 affiche CE‑110032‑7. Ensuite, repasser la PS5 sur le 🟢 compte de jeu.",
        "hc5_xbox" to "Une fois, sur la page Xbox (menu Console) : Connecter un compte Microsoft → sur le téléphone ou l’ordinateur, ouvrir microsoft.com/link (ou scanner le QR code), saisir le code affiché et se connecter avec le compte Microsoft utilisé pour jouer sur la Xbox – pas besoin de deuxième compte ici. L’e-mail et le mot de passe se saisissent uniquement sur la page de Microsoft, jamais dans ReCaption. Ensuite, choisir la Xbox sur laquelle on joue.",
        "hc6" to "6. Jouer",
        "hc6_android" to "Sur Accueil, lancer la traduction, attendre « l’image arrive » et passer le téléviseur sur l’HDMI de la console. Les sous-titres anglais doivent être activés dans le jeu. L’apparence et la position du bandeau se changent dans Sous-titres.",
        "hc6_tv" to "Lancer la traduction dans ReCaption (téléphone). Sur le téléviseur, ouvrir l’appli ReCaption et choisir l’HDMI de la console : elle trouve le téléphone toute seule. Les sous-titres anglais doivent être activés dans le jeu. L’apparence du bandeau se change dans Sous-titres sur le téléphone, ou en jouant avec OK sur la télécommande du téléviseur. Le téléphone peut rester posé, idéalement en charge ; l’écran ne doit pas s’éteindre – ⚙ Réglages → Général → « Ne pas éteindre l'écran du téléphone ».",
        "hc7" to "7. Quand quelque chose ne marche pas",
        "hc7_qr" to "La page du QR code ne s’ouvre pas sur le téléphone : le téléphone doit être sur le même Wi-Fi (pas en données mobiles).",
        "hc7_ps5" to "La console ne se connecte pas : vérifier Remote Play pour le deuxième utilisateur et que la console et cet appareil sont sur le même réseau.",
        "hc7_net" to "La connexion décroche : en Wi-Fi 2,4 GHz, les manettes de la console utilisent la même bande. Solution : relier la console au routeur par câble ou passer cet appareil en Wi-Fi 5 GHz.",
        "hc7_battery" to "Téléphone : la connexion décroche écran éteint – dans ⚙ Réglages → Général activer « Autoriser en arrière-plan » (l’économie de batterie met ReCaption en veille).",
        "hc7_screen" to "Téléphone : écran éteint, la traduction ralentit ou s’arrête presque (Samsung lit les sous-titres jusqu’à 10× plus lentement) – activer ⚙ Paramètres → Général → « Ne pas éteindre l'écran du téléphone » (l’écran reste assombri), idéalement avec le téléphone en charge.",
        "hc7_other" to "La PS5 affiche sans cesse « manette déconnectée / compte connecté » : un autre appareil se connecte avec le même deuxième compte (par ex. l’appli PS Remote Play). Le deuxième compte doit servir uniquement à ReCaption.",
        "hc7_read" to "Aucun sous-titre n’apparaît : activer ⚙ Réglages → Expérimental → Mode diagnostic pour voir ce que lit l’appli. Un rapport d’erreur envoyé au téléphone aide aussi.",
        "hc8" to "8. Options des Réglages",
        "hc9" to "9. Plusieurs téléviseurs ou consoles",
        "hc9_text" to "•  Autre PS5 : page Console → « Associer une autre PS5 » ; on passe de l’une à l’autre avec la ligne « PS5 active ».\n•  PS5 et Xbox : ⚙ Réglages → Général → Console ; l’association et la connexion restent enregistrées.\n•  Deux téléviseurs LG / Samsung, un téléphone : le téléphone retient l’apparence des sous-titres et les zones de chaque téléviseur.\n•  Deux Android TV : ReCaption sur chacune ; chacune a ses propres réglages.",
        "hm_row" to "Plusieurs téléviseurs ou consoles",
        "help_page" to "Page du guide",
        "ls_other_device" to "Remote Play sur la PS5 est utilisé maintenant par un autre appareil avec le même compte (par ex. l’appli PS Remote Play). ReCaption se connectera dès qu’il sera libre.",
        "pv_stale" to "L’aperçu est la dernière image reçue – l’image n’arrive pas en ce moment :",
        "lg_launch" to "Lancer ReCaption sur le téléviseur",
        "tv_current" to "ReCaption est sur le téléviseur (version %s)",
        "lg_pass_other" to "Saisir à nouveau la Passphrase",
        "vg_error" to "Impossible de charger la vidéo. Vérifier la connexion Internet ou ouvrir l’adresse dans un navigateur :",
    ),
    Lang.IT to mapOf(
        "help_for" to "Installazione per",
        "hc1" to "1. Installare ReCaption",
        "hc1_android" to "ReCaption va sull’Android TV o sul box Android collegato al televisore. ReCaption.apk si installa con l’app Downloader – basta inserire il codice 8438934 (in alternativa l’indirizzo della pagina della guida) o da una chiavetta USB con un file manager. Le versioni successive vengono proposte da sole in Home.",
        "hc1_reader" to "I televisori LG e Samsung non sanno leggere da soli l’immagine del gioco. Per questo ReCaption funziona su un telefono Android (o un box): legge l’immagine della console, traduce e invia i sottotitoli pronti all’app ReCaption sul televisore. Scaricare ReCaption.apk sul telefono e installarlo (il link è nella pagina della guida).",
        "hc2" to "2. Preparare la console",
        "hc2_ps" to "Sulla PS5 aggiungere un 🔵 secondo utente con un altro account PlayStation (gratis). L’app si collega con quello: con l’🟢 account di gioco la console scollegherebbe il controller durante il gioco. Un account creato sul web va ancora aggiunto sulla PS5: icona del profilo → Cambia utente → Aggiungi utente e accedere con l’🔵 account (non come ospite). Per il 🔵 secondo utente attivare Impostazioni → Sistema → Riproduzione remota → Abilita Riproduzione remota. Poi si gioca come sempre con l’🟢 account di gioco.",
        "hc2_xbox" to "Sulla Xbox attivare Impostazioni → Dispositivi e connessioni → Funzionalità remote e lasciare la modalità di alimentazione su «Sospensione» (non risparmio energia). Poi nella pagina Xbox di ReCaption accedere con un account Microsoft con il codice su microsoft.com/link e scegliere la Xbox.",
        "hc3" to "3. Televisore",
        "hc3_android" to "ReCaption disegna la barra di traduzione sopra l’immagine del gioco. Va consentito nelle impostazioni del televisore: Accessibilità → ReCaption → Attiva (oppure «Mostra sopra altre app»). Se il televisore non ha quella schermata, si può consentire da un computer:",
        "hc3_lg" to "Sul televisore LG va l’app ReCaption (schermata con il gioco e la barra). Si installa da questo dispositivo tramite la modalità sviluppatore LG: l’assistente guida passo passo e spunta da solo i passi fatti. La modalità sviluppatore scade dopo un po’; Home avvisa in tempo. Questo dispositivo deve essere nella stessa rete di casa del televisore. La modalità sviluppatore si estende sul televisore, nell’app Developer Mode (Extend), oppure ReCaption la prolunga una volta al giorno con l’opzione ⚙ → Generali → Prolungare la modalità sviluppatore. Quando scade, ReCaption sparisce dal televisore e va installato di nuovo. Si può installare anche da computer con lo strumento LG ares (istruzioni su recaption.pages.dev/lg.html#pocitac cartella webos).",
        "hc4" to "4. Lingua e qualità della traduzione",
        "hc4_text" to "La lingua di traduzione si sceglie in Sottotitoli. Sotto, «Traduci da» è la lingua dei sottotitoli del gioco (inglese per impostazione predefinita). Il pacchetto lingua si scarica una volta (circa 30 MB), poi la traduzione è offline e gratuita. Una traduzione migliore con DeepL (chiave personale gratuita) si imposta in Sottotitoli → Qualità della traduzione: sulla TV basta scansionare un codice QR – la pagina sul telefono guida nella registrazione a DeepL, nella copia e nell’incolla della chiave.",
        "hc5" to "5. Associare la console",
        "hc5_text" to "Una volta, seguendo la guida nella pagina Console: scegliere il 🔵 secondo account (per ReCaption), accedere con il telefono (codice QR) e sulla PS5, con lo stesso utente, attivare Riproduzione remota e richiedere il numero di otto cifre. Se lo richiede un altro utente, la PS5 mostra CE‑110032‑7. Poi sulla PS5 tornare all’🟢 account di gioco.",
        "hc5_xbox" to "Una volta, nella pagina Xbox (menu Console): Accedi con un account Microsoft → sul telefono o sul computer aprire microsoft.com/link (o scansionare il codice QR), inserire il codice mostrato e accedere con l’account Microsoft con cui si gioca sulla Xbox – qui non serve un secondo account. E-mail e password si inseriscono solo sulla pagina di Microsoft, non in ReCaption. Poi scegliere la Xbox su cui si gioca.",
        "hc6" to "6. Giocare",
        "hc6_android" to "In Home avviare la traduzione, aspettare «l’immagine arriva» e passare il televisore all’HDMI della console. I sottotitoli in inglese nel gioco devono essere attivi. Aspetto e posizione della barra si cambiano in Sottotitoli.",
        "hc6_tv" to "Avviare la traduzione in ReCaption (telefono). Sul televisore aprire l’app ReCaption e scegliere l’HDMI della console: trova il telefono da sola. I sottotitoli in inglese nel gioco devono essere attivi. L’aspetto della barra si cambia in Sottotitoli sul telefono o, giocando, con OK sul telecomando del televisore. Il telefono può restare appoggiato, meglio in carica; lo schermo non deve spegnersi – ⚙ Impostazioni → Generali → «Non spegnere lo schermo del telefono».",
        "hc7" to "7. Quando qualcosa non va",
        "hc7_qr" to "La pagina del codice QR non si apre sul telefono: il telefono deve essere sulla stessa Wi-Fi (non sui dati mobili).",
        "hc7_ps5" to "La console non si collega: controllare la Riproduzione remota del secondo utente e che console e questo dispositivo siano sulla stessa rete.",
        "hc7_net" to "La connessione cade: sulla Wi-Fi a 2,4 GHz i controller della console usano la stessa banda. Aiuta collegare la console al router via cavo o passare questo dispositivo alla Wi-Fi a 5 GHz.",
        "hc7_battery" to "Telefono: la connessione cade a schermo spento – in ⚙ Impostazioni → Generali attivare «Consenti uso in background» (il risparmio batteria sospende ReCaption).",
        "hc7_screen" to "Telefono: a schermo spento la traduzione rallenta o quasi si ferma (Samsung legge i sottotitoli fino a 10× più lentamente) – attivare ⚙ Impostazioni → Generali → «Non spegnere lo schermo del telefono» (lo schermo resta attenuato), meglio con il telefono in carica.",
        "hc7_other" to "Sulla PS5 compare di continuo «controller scollegato / account collegato»: un altro dispositivo si collega con lo stesso secondo account (ad es. l’app PS Remote Play). Il secondo account deve servire solo a ReCaption.",
        "hc7_read" to "Non compaiono sottotitoli: attivare ⚙ Impostazioni → Sperimentale → Modalità diagnostica per vedere cosa legge l’app. Aiuta anche una segnalazione inviata al telefono.",
        "hc8" to "8. Opzioni delle Impostazioni",
        "hc9" to "9. Più televisori o console",
        "hc9_text" to "•  Un’altra PS5: pagina Console → «Associa un’altra PS5»; tra quelle associate si passa con la riga «PS5 attiva».\n•  PS5 e Xbox: ⚙ Impostazioni → Generali → Console; associazione e accesso restano salvati.\n•  Due televisori LG / Samsung, un telefono: il telefono ricorda l’aspetto dei sottotitoli e le aree di ogni televisore.\n•  Due Android TV: ReCaption su ciascuna; ognuna ha le proprie impostazioni.",
        "hm_row" to "Più televisori o console",
        "help_page" to "Pagina della guida",
        "ls_other_device" to "La Riproduzione remota della PS5 ora è usata da un altro dispositivo con lo stesso account (ad es. l’app PS Remote Play). ReCaption si collegherà quando sarà libera.",
        "pv_stale" to "L’anteprima è l’ultimo fotogramma ricevuto – ora l’immagine non arriva:",
        "lg_launch" to "Avviare ReCaption sul televisore",
        "tv_current" to "ReCaption è sul televisore (versione %s)",
        "lg_pass_other" to "Inserire di nuovo la Passphrase",
        "vg_error" to "Impossibile caricare il video. Controllare la connessione a internet o aprire l’indirizzo in un browser:",
    ),
)
